import{_ as l,o as p,c as e,a3 as t}from"./chunks/framework.DdpBa4_E.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/38-在舒适地带中共生.md","filePath":"books/attached/38-在舒适地带中共生.md","lastUpdated":1794298621000}'),i={name:"books/attached/38-在舒适地带中共生.md"};function _(o,a,r,n,u,s){return p(),e("div",null,[...a[0]||(a[0]=[t('<h3 id="在舒适地带中共生" tabindex="-1">在舒适地带中共生 <a class="header-anchor" href="#在舒适地带中共生" aria-label="Permalink to &quot;在舒适地带中共生&quot;">​</a></h3><p>瑞恩（Ryan）与肖娜（Shauna）的恋情，产生于办公室之中。瑞恩在另一家知名公司找到高薪工作，跳槽之前，他们俩已经作为同事交往了好几个月。瑞恩刚调走后，这对恋人并不会在工作日腻在一起。而当瑞恩和新同事头一次去出差时，他实在是非常思念肖娜，准备打电话给她。而电话响了两声以后，就转入了语音信箱。他感觉有点不对，心里不太舒服，又拨了一个电话。而这一次，电话直接转入了语音信箱。他并没有给肖娜留言，对于她看到第一个来电以后按下“忽略”键，而第二个电话直接挂掉了，瑞恩感到非常受伤。他发现自己根本不能专心致志地开会，但是他已经告诫过自己，出差回去之前都不会再给她打电话了。不过所幸的是，一个小时以后肖娜就发来了道歉短信，解释说没能接电话是因为当时上司就站在自己旁边，实在不方便接听。他看到以后立马消了气，给她回了电话。</p><p>瑞恩就属于典型的第六感灵敏的焦虑型依恋风格。他的情绪常常因为女朋友一点点细微的存在感变化而被牵动，比如说，他甚至会数着电话在接入语音信箱之前响了多少声。他还准确地得出了这样的判断：肖娜头一次按了“忽略”按钮，而第二次挂掉了电话，要是换作其他依恋风格的人，很可能注意不到这些细节。而他之所以会如此敏感，是因为从前他跟肖娜在工作日的距离，不过相隔着三间办公室，而这次是他在新公司的第一次外出公干，因此并没有完全适应这种距离的分隔。不过肖娜属于安全型依恋风格，并且可以轻而易举地对瑞恩的举动做出有效回应，并且修复他们之间的嫌隙，让对方即将触发的依恋机制得以平息，这对瑞恩来说是件好事。与艾米莉不同，瑞恩并没有感觉到自己的恋情进入了危险地带，因为他的焦虑得到了及时的安抚。</p><p>显然，如果在恋爱中的某一时刻，你感觉不安，其实只是需要伴侣的一个小小安抚，比如说和肖娜一样的短信，就能让你恢复平静。而相反，如果没有得到那份安抚，你对于恋情的不安全感就会成倍增长，这时候，仅仅是一条信息恐怕就很难平息你的依恋机制了。你和伴侣之间的交流默契越早达成，往后你们在处理问题时所花的精力就越少。</p><p>事实上，如果肖娜当时没有及时反馈瑞恩，他就会继续无心工作，也就是依恋机制的触发。当肖娜最后回电话过去时，他要么会直接冷漠不回应，要么就会在电话里发火，也就是采取一些防御策略。而不论是哪一种结果，都会对恋情产生致命的伤害。</p><p>防御行为——会让你被依恋机制打败</p><p>太想与恋人取得联系：</p><ul><li>不断地打电话、发短信、发邮件；痴痴等着对方的电话；在你伴侣公司楼下闲逛，只为早点见到对方。</li></ul><p>退缩：</p><ul><li>沉默不语，佯装专心地阅读文件，假装不理会你的伴侣；故意不说话；故意和别人讲电话，不理你的伴侣。</li></ul><p>计分策略：</p><ul><li>记下对方时隔多久接起了你的电话，并在今后也隔那么久接他的电话；在产生矛盾以后，等着对方先开口“破冰”，否则就一直采取冷战。在瑞恩发现肖娜挂电话以后，决定再也不发信息给她了，这就是一种计分策略：她要是不接我电话，那我就不发信息给她。</li></ul><p>表现出敌意：</p><ul><li>在对方说话的时候翻白眼、不看着他，或者直接起身出门，而表现敌意非常容易将内在的小分歧转化为严重的争吵。</li></ul><p>以分手相要挟：</p><ul><li>提出一系列威胁，比如：“我觉得我们到头了，我一刻也无法忍受了。””我看出来了，我俩根本不适合！””没了你，我能过得更好！”，这一切只是希望对方挽留你。</li></ul><p>玩些小把戏：</p><ul><li>假装很忙碌，无暇顾及对方的样子。比如不接电话，或者编造一些莫须有的事务安排。</li></ul><p>让对方吃醋：</p><ul><li>准备约某位前任吃个午饭；跟朋友一起去单身酒吧玩；跟伴侣说，今天某个人跟你调情了。</li></ul><p>防御行为就是那些试图建立与伴侣之间的关系，或是引起他们注意的行为。防御行为有很多表现形式，毕竟很多举动都可以促使他人注意到你，或是对你产生回应。</p><p>但是，防御行为和触发机制也很可能让你产生一些不利于恋情的行为。因此，及时地意识到它们的发生，是非常重要的。在第8章，我们会详细地介绍亲密关系的类目，它们可以帮助你辨别出防御行为的产生。同时也能在面对艰难处境时，帮助你采取更多建设性的有效行为。这些防御行为和策略，很可能在你与恋人分手以后，还长期存在着。因此，这也解释了为何我们会因为分手而心痛，虽然对方已然离去，但是我们的身心依然没有平静，依然正在渴望着对方能够归来。即使理智告诉你，别再想着那个人，但依恋机制很可能让你没法完全解脱。依恋机制有着其自己的运作轨迹和步调。这也就意味着，彻底忘记一个人，将其从脑海里面抹去，可能需要很长一段时间。</p><p>焦虑型依恋风格的人群尤其敏感，更容易陷入长时间的依恋机制激活状态中。由欧姆瑞·吉拉斯（Omri Gillath）、西尔维亚·邦奇（Silvia Bunge）、卡特·温德肯（Carter Wendelken）以及两位依恋理论先驱菲利普·谢弗、马里奥·米库里茨（Mario Mikulincer）共同合作的一项研究中，就发现了一些有趣的证据，证实了这个结论。通过功能性核磁共振技术对大脑进行扫描，他们让20位女性对于不同的恋爱进行想象，而后要求她们停止这些想象。令人惊讶的是，研究者发现，那些处于焦虑型依恋风格的女性在想到一些消极的场景，诸如冲突、分手或者丧偶时，她们大脑中的情感反射区域的活跃程度，要远比其他依恋风格的被试高。与此同时，焦虑型依恋风格的被试们调控情感的大脑区域，比如前额叶皮层，则远不及其他依恋风格的被试活跃。换句话说，焦虑型依恋风格人群的大脑对于消极情绪的反应会更加强烈，而担任情感控制和调节职能的脑区，其活跃度则比较低。也就是说，当一个人的依恋机制一旦激活，而这个人又恰恰是焦虑型依恋风格，那这种依恋机制就很难平复下去了。</p><p>对于焦虑型依恋风格的人来说，了解自己的依恋机制是非常重要的。这对于他们获得完满的恋情非常有利。</p><p>通常对于焦虑型依恋风格的人，往往采取两条指引路径，第一条是针对那些暂时单身、无人可以依恋的人，第一时间找到一个安全型的恋人无疑是最佳选择。这的确可以将很多麻烦防患于未然，不过进入完全安全的状态，往往要比你想象的困难。这一章接下来的内容，正是针对焦虑型依恋风格的单身人士，教他们如何找到一位安全型的恋人并且在此过程中少走弯路。而第二条则是送给已经在恋爱中，但是尚在考察自己的伴侣是否值得托付的那些焦虑型依恋风格人群。其更注重你的依恋机制重塑，其中最主要的工作就是对恋爱中自己的态度和观点重新审视，而这种依恋机制的转变，正是用更多安全型恋爱技巧来武装自己的一个过程。在第三和第四部分，我们会着重探讨着这一个群体。</p>',25)])])}const h=l(i,[["render",_]]);export{c as __pageData,h as default};
